import { useCallback } from 'react';

// Mock DOMPurify for sandbox:
const DOMPurify = {
  sanitize: (html, config) => {
    // Simple mock: strip script tags
    return html.replace(/<script[^>]*>.*?<\/script>/gi, '[removed]')
               .replace(/javascript:/gi, '[removed]:');
  },
};

// TODO 1: SafeLink — only allow https:// and relative URLs
function SafeLink({ href, children }) {
  // TODO: validate href — only allow https:// and /
  // If invalid, render as plain text or safe fallback
  return <a href={href} data-testid="safe-link">{children}</a>;
}

// TODO 2: RichText — sanitise before rendering
function RichText({ html }) {
  // TODO: sanitise with DOMPurify before dangerouslySetInnerHTML
  return <div data-testid="rich-text" dangerouslySetInnerHTML={{ __html: html }} />;
}

// TODO 3: useSecureFetch — adds CSRF token to mutating requests
function useSecureFetch() {
  return useCallback(async (url, options = {}) => {
    const method = options.method?.toUpperCase() || 'GET';
    const isStateChanging = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method);

    // TODO: add X-CSRF-Token header if state-changing
    const headers = {
      'Content-Type': 'application/json',
      ...options.headers,
      ...(isStateChanging ? { 'X-CSRF-Token': 'mock-csrf-token' } : {}),
    };

    return fetch(url, { ...options, headers });
  }, []);
}

export default function App() {
  return (
    <div data-testid="app">
      <SafeLink href="https://arcane.academy">Valid link</SafeLink>
      <SafeLink href="javascript:alert(1)">XSS attempt</SafeLink>
      <RichText html="<p>Safe content</p><script>alert('xss')</script>" />
    </div>
  );
}
